def get_input_types(class_name: str) -> list[tuple[int, str]]:
    """Return [(port_index, type_str), ...] for fixed inputs."""
    entry = OPERATOR_PORT_REGISTRY.get(class_name)
    if not entry:
        return []
    return [(i["port"], i["type"]) for i in entry["inputs"]]


def get_output_types(class_name: str) -> list[tuple[int, str]]:
    """Return [(port_index, type_str), ...] for outputs."""
    entry = OPERATOR_PORT_REGISTRY.get(class_name)
    if not entry:
        return []
    return [(o["port"], o["type"]) for o in entry["outputs"]]


def get_dynamic_input_type(class_name: str) -> str | None:
    """Return the family type for dynamic inputs, or None."""
    entry = OPERATOR_PORT_REGISTRY.get(class_name)
    if not entry:
        return None
    return entry["dynamic_inputs"]


def accepts_input_type(class_name: str, port: int, family_type: str) -> bool:
    """Check if class_name accepts family_type on the given port."""
    entry = OPERATOR_PORT_REGISTRY.get(class_name)
    if not entry:
        return False
    # Check fixed inputs
    for i in entry["inputs"]:
        if i["port"] == port:
            return i["type"] == family_type or i["type"] == "ANY"
    # Check dynamic inputs (any port index >= number of fixed inputs)
    dyn = entry["dynamic_inputs"]
    if dyn:
        return family_type == dyn or dyn == "ANY"
    return False
